(function(root){
'use strict';
const items=[{"id":"sexual-conduct","topic":"Scope and forum","question":"Is every bullying, rude remark or workplace dispute a POSH complaint?","answer":["Not every workplace grievance is sexual harassment under the POSH Act. Consider whether the reported conduct has a sexual element under Section 2(n), together with any connected circumstances under Section 3(2). A label such as bullying or unfair treatment does not decide the legal classification.","Other grievances can still be serious and may need a different employment, disciplinary or legal route. The free guidance helps identify questions to review; it does not determine jurisdiction, guilt or legal merits."],"basis":"Sections 2(n) and 3(2)","source":"act","popular":false,"keywords":"bullying harassment discrimination hostile environment"},{"id":"who-is-protected","topic":"Scope and forum","question":"Must an aggrieved woman be a permanent employee?","answer":["No. The Act’s definitions extend beyond permanent employees. An aggrieved woman may be employed or not employed at the workplace, and the employee definition covers several working arrangements.","The actual workplace connection and competent forum still need review. Do not rule out a concern solely because someone is an intern, contract worker, applicant or visitor."],"basis":"Sections 2(a), 2(f) and 2(o)","source":"act","popular":false,"keywords":""},{"id":"workplace-connection","topic":"Scope and forum","question":"Can conduct away from the office or online have a workplace connection?","answer":["The statutory concept of workplace is broader than an office desk. Work-related visits, activities and other circumstances can matter. Online conduct should be assessed in its factual work context rather than automatically included or excluded.","The location or communication channel alone does not establish a POSH case. Preserve lawful records and obtain a competent assessment of the connection."],"basis":"Sections 2(o), 2(n) and 3","source":"act","popular":false,"keywords":""},{"id":"ic-or-lc","topic":"Scope and forum","question":"What is the difference between the IC and the LC?","answer":["The Internal Committee (IC) is constituted at the workplace under Section 4. The Local Committee (LC) is constituted at district level. Section 6 addresses complaints from establishments with fewer than ten workers and complaints against the employer.","Forum selection must take account of the actual employer, establishment, Committee constitution and complaint. This website does not appoint, validate or choose a Committee for a live matter."],"basis":"Sections 4, 6 and 7","source":"act","popular":true,"keywords":"ICC LCC internal local ten employees jurisdiction employer"},{"id":"missing-or-unknown-ic","topic":"Scope and forum","question":"What if there is no IC, or I cannot find its details?","answer":["An IC that has not been constituted is different from an IC whose details you do not know. Ask for the constitution order, membership and contact details; seek appropriate employer or District Officer assistance promptly.","Protect the applicable complaint window while checking the forum. Do not wait indefinitely, assume that missing contact information proves non-constitution, or rely on this website to confirm LC competence in your particular circumstances."],"basis":"Sections 4, 6 and 9","source":"act","popular":true,"keywords":"missing absent unknown no committee escalation"},{"id":"different-employers","topic":"Scope and forum","question":"Does having different employers automatically prevent an inquiry?","answer":["Do not treat different employers as an automatic bar. The statutory wording and the relevant workplace facts need to be considered alongside current case law, the respondent’s applicable service rules and coordination between authorities.","The Section 11(1) safeguard refers to both parties being employees; it does not use the expression same employer. This does not mean that every Committee automatically has jurisdiction over every outside respondent."],"basis":"Section 11(1); forum and service-rule review","source":"judgment","popular":false,"keywords":"same employer different organisation external respondent"},{"id":"complaint-window","topic":"Complaint and timelines","question":"Is the complaint period three months or six months?","answer":["The normal Section 9 period is three months from the incident, or from the last incident in a series. A further extension of up to three months is possible where the Committee is satisfied about the circumstances preventing timely filing and records its reasons.","Six months is therefore not the automatic standard filing window. Do not assume an extension will be granted, or treat the site’s indicative date handling as a limitation decision."],"basis":"Section 9","source":"act","popular":false,"keywords":"limitation delay late extension 3 months 6 months"},{"id":"calendar-working-days","topic":"Complaint and timelines","question":"Are all POSH timelines working days?","answer":["No. The provisions use different units. Section 9 uses months; the Central Rule 7 complaint-copy and reply provisions use working days; the Act’s inquiry, report, action and appeal provisions state periods in days.","Check the exact provision, triggering event, applicable rules and calendar. Do not convert every deadline into working days or rely on a generic online calculator as an authoritative due date."],"basis":"Section 9; Central Rule 7; Sections 11, 13 and 18","source":"act","popular":false,"keywords":"calendar holidays counting dates deadlines"},{"id":"help-writing","topic":"Complaint and timelines","question":"Can someone get help if they cannot prepare a written complaint?","answer":["Section 9 provides for reasonable assistance in reducing a complaint to writing where the woman cannot do so. The permitted representative routes for incapacity, death or other specified circumstances have their own conditions under Section 9(2) and Central Rule 6.","The free Word draft is only a preparation aid. It neither replaces the statutory assistance duty nor gives every person an unrestricted right to file on someone else’s behalf."],"basis":"Section 9; Central Rule 6","source":"act","popular":false,"keywords":"oral complaint disability representative relative friend"},{"id":"seven-day-acceptance","topic":"Complaint and timelines","question":"Must the Committee accept or reject a complaint within seven days?","answer":["There is no general seven-day acceptance or rejection deadline in the provisions shown here. Under applicable Central Rule 7(2), the Committee must send the complaint copy to the respondent within seven working days of receipt.","Do not use a preliminary review to assume that applicable service obligations have stopped. Receipt, service and jurisdiction questions need accurate records and review under the applicable framework."],"basis":"Central Rule 7(2)","source":"rules","popular":true,"keywords":"7 days acceptance rejection preliminary review notice"},{"id":"submission-receipt","topic":"Complaint and timelines","question":"Are submission, receipt and acknowledgement the same thing?","answer":["No. Sending a complaint does not independently prove when the competent authority received it or what was acknowledged. Keep your submission record and seek a dated acknowledgement or receipt.","This website cannot establish those events. The date you select in the guidance remains your stated information; a generated document is not evidence that an IC, LC or employer has received or accepted it."],"basis":"Section 9; product filing boundary","source":"act","popular":false,"keywords":"filed email acknowledgment receipt service"},{"id":"respondent-reply","topic":"Complaint and timelines","question":"When does the respondent’s reply period start?","answer":["Under applicable Central Rule 7(3), the reply is due within ten working days after receipt of the prescribed complaint documents. The complaint-copy service period is a separate seven-working-day requirement.","Confirm actual service, materials and applicable rules; do not calculate from an unrelated email or assume the same procedural scheme applies in every workplace."],"basis":"Central Rule 7(1)–(3)","source":"rules","popular":false,"keywords":"10 days notice served documents particulars"},{"id":"conciliation-voluntary","topic":"Conciliation and confidentiality","question":"Is conciliation compulsory before an inquiry?","answer":["No. Section 10 contemplates conciliation at the aggrieved woman’s request before the inquiry begins. It should not be treated as a mandatory compromise step or a reason to pressure either party.","The website’s optional request draft does not prove that a request is voluntary, that settlement terms are lawful, or that the competent Committee has recorded a settlement."],"basis":"Section 10","source":"act","popular":false,"keywords":"mediation settlement voluntary pressure"},{"id":"money-settlement","topic":"Conciliation and confidentiality","question":"Can a monetary settlement be the basis of Section 10 conciliation?","answer":["No. Section 10 expressly excludes monetary settlement as the basis of conciliation. This is distinct from the Act’s separate provisions concerning recommendations and compensation following an inquiry.","Do not use a payment promise to bypass statutory procedure or treat this FAQ as approval of proposed settlement terms."],"basis":"Sections 10, 13 and 15","source":"act","popular":false,"keywords":"money compensation cash settlement"},{"id":"settlement-breach","topic":"Conciliation and confidentiality","question":"What if the respondent does not comply with a recorded settlement?","answer":["The Section 11(1) proviso addresses the situation where the aggrieved woman informs the Committee that a term or condition of the Section 10 settlement has not been complied with. The statutory route includes proceeding with inquiry or, as applicable, forwarding the complaint to police.","The response is not decided by this website, and a breach should not be treated as automatically establishing every underlying allegation."],"basis":"Section 11(1), first proviso","source":"act","popular":false,"keywords":""},{"id":"nda-required","topic":"Conciliation and confidentiality","question":"Must I sign an NDA before I can file a POSH complaint?","answer":["The POSH complaint provisions do not prescribe signing an NDA as a statutory filing condition. An institution may use a role-appropriate confidentiality undertaking, but it must be distinguished from the confidentiality duty imposed by law.","Any proposed undertaking should be reviewed so it preserves lawful reporting, fair-process disclosure and statutory remedies. The public demo does not generate an NDA or determine whether a particular contract is enforceable."],"basis":"Sections 9 and 16; institutional safeguard","source":"act","popular":true,"keywords":"NDA non disclosure confidentiality undertaking gag signature"},{"id":"confidentiality-without-nda","topic":"Conciliation and confidentiality","question":"Does confidentiality apply if nobody has signed an NDA?","answer":["Yes. Section 16 addresses public disclosure of complaint contents, identities and specified information about conciliation, inquiry, recommendations and action. The statutory duty does not arise only when an institutional form is signed.","Confidentiality must be applied alongside the parties’ procedural rights and lawful disclosures. A public community post is not a confidential channel for sharing case details."],"basis":"Sections 16 and 17; Sections 11 and 13","source":"act","popular":false,"keywords":"privacy public media witness identities disclosure"},{"id":"applicable-procedure","topic":"Inquiry and evidence","question":"Should every Committee use the Central Rules in exactly the same way?","answer":["Section 11(1) requires attention to the service rules applicable to an employee respondent and the prescribed procedure where such rules do not exist. Sector, institutional and jurisdictional frameworks can therefore matter.","The Central Rules references in this overview are qualified where applicable. They do not replace checking the governing procedure for a live case."],"basis":"Section 11(1)","source":"act","popular":false,"keywords":"service rules central rules government private sector"},{"id":"ninety-day-inquiry","topic":"Inquiry and evidence","question":"Which provision gives the inquiry its 90-day limit?","answer":["Section 11(4) sets the inquiry-completion period at ninety days. Section 11(1) concerns the inquiry framework and contains additional safeguards; it is not the subsection that states the ninety-day limit.","The overview separates those references deliberately. Do not interpret the lack of a separate deadline for every individual hearing or evidence step as permission to ignore the overall period."],"basis":"Section 11(1) and Section 11(4)","source":"act","popular":false,"keywords":"90 days stage 5 duration timeline"},{"id":"appreciation-evidence","topic":"Inquiry and evidence","question":"What does appreciation of evidence mean?","answer":["It means considering what the available material establishes, including its relevance, reliability, consistency and weight in the particular inquiry. Witness examination and appreciation of evidence are related but not identical activities.","It is not a mechanical score, a count of documents or an automatic finding of guilt. The free overview neither evaluates a person’s credibility nor produces findings for a live case."],"basis":"Section 11; natural justice under applicable Central Rule 7(4)","source":"act","popular":false,"keywords":"evaluation assessment proof witness credibility scoring"},{"id":"absence-ex-parte","topic":"Inquiry and evidence","question":"Does missing a hearing automatically mean an ex-parte decision or guilt?","answer":["No. Applicable Central Rule 7(5) addresses three consecutive hearing absences without sufficient cause and requires written notice fifteen days in advance before termination or an ex-parte order.","The safeguard does not equate absence with proof of guilt. Actual notice, reasons and governing procedure still matter."],"basis":"Central Rule 7(5)","source":"rules","popular":false,"keywords":"absent missed hearing ex parte default 15 days"},{"id":"hearing-quorum","topic":"Inquiry and evidence","question":"How many Committee members must attend an inquiry hearing?","answer":["Applicable Central Rule 7(7) requires at least three members, including the Presiding Officer or Chairperson. Attendance at a hearing is different from the Committee’s overall constitution.","A checkbox or website statement cannot validate the constitution, membership or attendance of a real Committee."],"basis":"Central Rule 7(7); Sections 4 and 7","source":"rules","popular":false,"keywords":"quorum three members presiding chairperson"},{"id":"lawyer-representation","topic":"Inquiry and evidence","question":"Can a lawyer represent a party before the Committee?","answer":["Central Rule 7(6), where applicable, bars representation by a legal practitioner in proceedings before the Committee. Verify the governing service-rule and procedural framework.","Distinguish representation in the hearing from seeking independent legal advice outside it."],"basis":"Central Rule 7(6); Section 11(1)","source":"rules","popular":false,"keywords":"advocate lawyer assistance representative"},{"id":"interim-relief","topic":"Inquiry and evidence","question":"Must a woman wait for the final report before asking for protection?","answer":["No. Section 12 provides a route for interim recommendations on the aggrieved woman’s written request while inquiry is pending. It includes transfer-related relief and up to three months of additional leave; applicable Rule 8 addresses certain reporting or supervision arrangements.","These are not automatic outcomes or findings against the respondent. The competent Committee and employer have their respective statutory roles."],"basis":"Section 12; Central Rule 8","source":"act","popular":false,"keywords":"interim safety transfer leave appraisal supervisor retaliation"},{"id":"findings-representation","topic":"Findings, reports and remedies","question":"Why should parties receive findings before the completed report stage?","answer":["The second proviso to Section 11(1) provides, where both parties are employees, for an opportunity to be heard and access to findings so they can make representations against them before the Committee.","This safeguard is distinct from giving the concerned parties the completed report under Section 13(1). Section 11(1) itself does not set a universal number of days for making those representations."],"basis":"Section 11(1), second proviso; Section 13(1)","source":"act","popular":true,"keywords":"preview findings representation draft report same employees stage 7"},{"id":"report-ten-days","topic":"Findings, reports and remedies","question":"When must the completed inquiry report be supplied?","answer":["Section 13(1) requires the Committee to provide its report to the employer or District Officer within ten days of inquiry completion and make it available to the concerned parties.","This ten-day report requirement must not be confused with the respondent’s ten-working-day reply provision or a supposed universal ten-day findings-representation period."],"basis":"Section 13(1); Central Rule 7(3)","source":"act","popular":false,"keywords":"10 days final report copy parties"},{"id":"action-sixty-days","topic":"Findings, reports and remedies","question":"Does the Committee itself carry out every final recommendation?","answer":["Section 13(4) requires the employer or District Officer to act on the recommendations within sixty days of receipt. The Committee’s report and the authority’s implementation are separate events.","Keep the actual report-delivery and action records. Neither a downloaded draft nor a community answer establishes that a recommendation has been implemented."],"basis":"Section 13(4)","source":"act","popular":false,"keywords":"60 days implementation employer district officer"},{"id":"unproved-not-malicious","topic":"Findings, reports and remedies","question":"Does an unproved complaint automatically become a false or malicious complaint?","answer":["No. Section 14 distinguishes inability to substantiate a complaint or provide adequate proof from the conditions for action concerning malicious or knowingly false complaints and false evidence. Malicious intent must be established through the prescribed process.","Neither an adverse outcome nor a disputed account should automatically trigger a finding of malice. This website makes no such determination."],"basis":"Section 14","source":"act","popular":true,"keywords":"false complaint malice insufficient evidence not proved retaliation"},{"id":"appeal-forum","topic":"Findings, reports and remedies","question":"Can I appeal, and does the website file it for me?","answer":["Section 18 provides an appeal route for the specified recommendations, penalties or non-implementation, with a ninety-day period from the recommendations. The proper court, tribunal or prescribed authority and applicable service rules require verification.","This website is not an appeal portal. An email, draft or community post here does not lodge an appeal or protect a limitation period."],"basis":"Section 18; applicable Central Rule 11","source":"act","popular":false,"keywords":"90 days appeal tribunal challenge non implementation"},{"id":"anonymous-community","topic":"Community and privacy","question":"Is the community completely untraceable?","answer":["No account, name, email address or phone number is requested for public posting. Generated aliases are attached separately to posts. That provides anonymity to other readers; it is not a promise of complete untraceability.","Hosts may process technical logs, and the application uses short-lived network fingerprints for basic limits. Free text can still identify you or someone else. Keep real case facts and identifying details out of posts."],"basis":"Current community privacy design","source":"community","popular":false,"keywords":"anonymous phone name IP privacy identity logs"},{"id":"community-review","topic":"Community and privacy","question":"Why is my question or answer not visible immediately?","answer":["Every question and answer enters a private pending-review queue. Only approved content becomes public, and each answer needs its own approval. Review is not a legal endorsement or a guarantee of response time.","Save your receipt if you need to refer to a submission. There are no member accounts, self-edit controls or email notifications in this version."],"basis":"Current moderation workflow","source":"community","popular":false,"keywords":"pending approval delay receipt no sign in"},{"id":"confidential-case-post","topic":"Community and privacy","question":"Can I upload my complaint, evidence or an NDA to get advice?","answer":["No. The community is for general discussion. Do not share names, employers, witness identities, phone numbers, detailed allegations, confidential documents or material that could identify a case.","There are no attachments or direct messages. Use the competent authority’s appropriate channels for case material; community moderation does not turn a public forum into a confidential professional consultation."],"basis":"Community boundaries; Section 16","source":"community","popular":false,"keywords":"upload documents case files evidence NDA personal details"},{"id":"community-answer-authority","topic":"Community and privacy","question":"Is a moderator-approved answer verified legal advice?","answer":["No. Generated aliases do not establish anyone’s identity, qualifications or authority. Approval is a publication-review decision, not confirmation that an answer is legally correct or suitable for your circumstances.","Check primary sources and obtain appropriate professional advice before acting on a particular matter. The platform does not appoint a Committee or contact authorities on your behalf."],"basis":"Community contribution status","source":"community","popular":false,"keywords":"expert lawyer verified advice official moderator"},{"id":"report-remove-post","topic":"Community and privacy","question":"How can I flag a post or ask for removal?","answer":["Use Report on an approved question or answer and choose the relevant reason. Reports go to private review. A moderator can edit, reject or hide content; hiding a question also makes its answers unavailable while the parent is not approved.","No member login or self-service editing/deletion account exists. Do not post additional identifying information to explain a removal request publicly."],"basis":"Current reporting and moderation workflow","source":"community","popular":false,"keywords":"delete edit remove report abuse privacy"},{"id":"free-versus-paid","topic":"Plans and using the site","question":"What is free, and what remains part of the planned paid platform?","answer":["The free offering includes both individual guidance journeys, editable local Word drafts, the basic nine-stage inquiry overview, this FAQ and the moderated community.","Detailed IC/LC case management, confidential case records, hearing tools, professional inquiry findings/report generation and NDA acknowledgement tracking are planned professional capabilities. A public FAQ explanation is not access to those tools."],"basis":"Current product scope","source":"plans","popular":false,"keywords":"free demo paid limits IC LC professional workspace"},{"id":"plan-users-duration","topic":"Plans and using the site","question":"What do the plan duration, user count and read-only period mean?","answer":["The planned case licences show a working period and a maximum authorised-user count: Essential six months/two users, Professional nine months/five users, Advanced twelve months/eight users and Institutional Plus twelve months/fifteen users.","The four listed paid licences include three additional read-only months and one-authorised-proceeding scope, subject to written terms. Read-only time does not promise continued editing, new case work or an automatic renewal. Government/Enterprise terms are contractual."],"basis":"Current commercial specification","source":"plans","popular":false,"keywords":"licence license users duration access read only multiple cases"},{"id":"institutional-price-tax","topic":"Plans and using the site","question":"Is Institutional Plus exactly ₹1,49,999 including GST?","answer":["The published price remains from ₹1,49,999. Institutional Plus requires an agreed proposal; applicable GST is additional. Government/Enterprise is custom-quoted.","Do not treat the displayed starting price as a final tax-inclusive invoice or an unlimited multi-case entitlement. Scope, authorised users, continuity, activation and other commercial terms must be agreed in writing."],"basis":"Current pricing and licence boundaries","source":"plans","popular":false,"keywords":"149999 1,49,999 Institutional Plus GST taxes quotation"},{"id":"payment-test-mode","topic":"Plans and using the site","question":"Is Razorpay connected, and will a test payment activate a plan?","answer":["Actual Razorpay testing is pending the owner’s test credentials. Without those credentials, checkout is disabled. The staging integration refuses live keys and is designed only for simulated test transactions.","A test transaction creates no real purchase, tax invoice, paid account or service entitlement. Do not enter real payment details into a test flow. Institutional and Government/Enterprise purchases still require a proposal or quotation."],"basis":"Current staging payment status","source":"plans","popular":false,"keywords":"Razorpay payment gateway test keys activation refund invoice"},{"id":"draft-not-filed","topic":"Plans and using the site","question":"Has downloading a complaint or reply filed or served it?","answer":["No. The Word file is generated locally as an editable draft using the relevant selections you supplied. Review and complete it, verify the appropriate route, and submit or serve it independently through an appropriate channel.","The platform does not email the document to an IC, LC, employer, police or court. It cannot confirm submission, receipt, acknowledgement, legal acceptance or service."],"basis":"Current document-generation boundary","source":"guidance","popular":false,"keywords":"DOCX Word download filing submission served acknowledged"},{"id":"urgent-support","topic":"Plans and using the site","question":"Can I rely on the FAQ or community for urgent safety or child-protection action?","answer":["No. They are not emergency, reporting or crisis-response channels, and nobody is contacted automatically. Seek appropriate local emergency, police, child-protection or professional assistance directly when circumstances require it.","A concern involving a child can engage separate legal duties and safeguards. Do not put a child’s identity or detailed statement into the community. The free guidance is preliminary and cannot carry out mandatory reporting for you."],"basis":"Safety boundary; separate child-protection duties","source":"guidance","popular":false,"keywords":"emergency child minor urgent police POCSO reporting"}];
const topics=[...new Set(items.map(x=>x.topic))];
const normalize=x=>String(x||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function filter(query='',topic='All topics'){const words=normalize(query).split(/\s+/).filter(Boolean);return items.filter(x=>(topic==='All topics'||x.topic===topic)&&words.every(w=>normalize([x.question,...x.answer,x.basis,x.keywords].join(' ')).includes(w)));}
if(typeof module==='object'&&module.exports){module.exports={items,topics,filter};return;}
const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sources={act:{label:'POSH Act — India Code',url:'https://www.indiacode.nic.in/bitstream/123456789/2104/1/A2013-14.pdf'},rules:{label:'Central Rules — official Gazette',url:'https://spniwcd.wcd.gov.in/uploads/pdf/1719914401_2NUqe91gql.pdf'},judgment:{label:'Supreme Court primary judgment',url:'https://api.sci.gov.in/supremecourt/2023/26792/26792_2023_3_1501_66764_Judgement_10-Dec-2025.pdf'},community:{label:'View community',url:'#community'},plans:{label:'View plans and limits',url:'#pricing'},guidance:{label:'Explore free guidance',url:'#journeys'}};
function render(app,path){
 let topic='All topics';const opened=new Set();const deepId=path.split('/')[1];if(deepId)opened.add(deepId);
 app.innerHTML=`<section class="app-heading"><div class="wrap"><div><a class="app-back" href="#home">← Back to homepage</a><small>FREQUENTLY ASKED QUESTIONS</small><h1 id="faq-page-title">Clear answers to common POSH questions.</h1><p>Understand the distinctions people often miss: forum, timelines, confidentiality, findings, community privacy and what the platform actually offers.</p></div><span class="app-mini">${items.length} answers · ${topics.length} topics</span></div></section><div class="app-bg"><div class="wrap workspace faq-shell"><aside class="faq-notice"><strong>General guidance, not a decision on your case.</strong><p>Applicable service, institutional, sector and jurisdictional rules must be checked. Central Rule 7 references are qualified where applicable. This page does not file a complaint, determine guilt or replace advice on a particular matter.</p><p>Search general terms only. Do not enter names or confidential case details. Search and topic filtering stay in your browser.</p></aside><section class="faq-popular" aria-labelledby="faq-popular-title"><h2 id="faq-popular-title">Start with the most common confusion</h2><div>${items.filter(x=>x.popular).map(x=>`<a href="#faq/${escape(x.id)}">${escape(x.question)}</a>`).join('')}</div></section><section class="faq-controls" aria-label="Find a question"><label for="faq-search">Search questions and answers</label><input id="faq-search" type="search" placeholder="Try: seven days, NDA, IC, appeal or payment" autocomplete="off" maxlength="160"><div class="faq-topics" role="group" aria-label="Filter FAQ topics">${['All topics',...topics].map(t=>`<button type="button" data-faq-topic="${escape(t)}" aria-pressed="${t==='All topics'}">${escape(t)}</button>`).join('')}</div><div class="faq-actions"><button type="button" class="btn btn-light" id="faq-expand">Expand matching answers</button><button type="button" class="btn btn-light" id="faq-collapse">Collapse answers</button><button type="button" class="btn btn-light" id="faq-reset">Clear filters</button></div></section><p id="faq-result-count" role="status" aria-live="polite"></p><div id="faq-results"></div><div id="faq-empty" class="faq-empty" hidden><h2>No matching question found.</h2><p>Try fewer words or another topic. For a general discussion, you can ask the moderated community without including personal details.</p><a href="#community" class="btn btn-light">Visit community</a></div><section class="faq-next"><h2>Choose your next step</h2><a href="#journeys" class="btn btn-dark">Free individual guidance</a> <a href="#demo" class="btn btn-light">Nine inquiry stages</a> <a href="#community" class="btn btn-light">General community questions</a><p>Public FAQ explanations do not unlock detailed paid inquiry tools. Professional workspace, NDA document handling and paid-service activation remain planned.</p></section></div></div>`;
 const results=app.querySelector('#faq-results'),search=app.querySelector('#faq-search');
 function apply(){const matches=filter(search.value,topic);app.querySelector('#faq-result-count').textContent=matches.length+' of '+items.length+' questions shown'+(topic==='All topics'?'':' · '+topic);app.querySelector('#faq-empty').hidden=matches.length>0;
 results.innerHTML=matches.map(x=>{const source=sources[x.source];return `<details class="faq-detail" id="faq-${escape(x.id)}" data-faq-id="${escape(x.id)}" ${opened.has(x.id)?'open':''}><summary><span class="faq-topic-label">${escape(x.topic)}</span><span>${escape(x.question)}</span></summary><div class="faq-answer">${x.answer.map(p=>`<p>${escape(p)}</p>`).join('')}<p class="faq-basis"><strong>Basis:</strong> ${escape(x.basis)} · <a href="${escape(source.url)}" ${source.url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${escape(source.label)}</a></p><a class="faq-permalink" href="#faq/${escape(x.id)}">Link to this answer</a></div></details>`}).join('');
 for(const button of app.querySelectorAll('[data-faq-topic]'))button.setAttribute('aria-pressed',String(button.dataset.faqTopic===topic));}
 results.addEventListener('toggle',e=>{if(!e.target.matches('[data-faq-id]'))return;if(e.target.open)opened.add(e.target.dataset.faqId);else opened.delete(e.target.dataset.faqId)},true);
 search.addEventListener('input',apply);
 for(const button of app.querySelectorAll('[data-faq-topic]'))button.addEventListener('click',()=>{topic=button.dataset.faqTopic;apply()});
 app.querySelector('#faq-expand').addEventListener('click',()=>{for(const d of results.querySelectorAll('details')){opened.add(d.dataset.faqId);d.open=true}});
 app.querySelector('#faq-collapse').addEventListener('click',()=>{for(const d of results.querySelectorAll('details')){opened.delete(d.dataset.faqId);d.open=false}});
 app.querySelector('#faq-reset').addEventListener('click',()=>{topic='All topics';search.value='';apply();search.focus()});
 apply();document.title='Detailed FAQs | POSH Inquiry Navigator';
 if(deepId){const item=app.querySelector('#faq-'+CSS.escape(deepId));if(item)requestAnimationFrame(()=>{item.scrollIntoView({block:'start'});item.querySelector('summary').focus({preventScroll:true})});else{app.querySelector('#faq-result-count').textContent='That answer link was not found. Browse or search all questions below.';}}
}
root.NavigatorFAQ={render};
})(typeof window==='undefined'?globalThis:window);
